    ios::sync_with_stdio(false);   // 关掉 cin/cout 与 C 标准流的同步
    cin.tie(nullptr);              // 解除 cin 与 cout 的绑定
    int t;                         // 测试用例组数
    cin >> t;
    while (t--) {                  // 逐组处理
        int sum = 0;               // 7 个数的总和
        int mx = INT_MIN;          // 7 个数里的最大值（初值取最小整数，保证第一次一定被更新）
        for (int i = 0; i < 7; i++) {
