// 所以 n * M 就是价值的上界 —— 上界能达到，答案恒为 n * max(a)。
#include <bits/stdc++.h>
using namespace std;

int main() {
    ios::sync_with_stdio(false);   // 关闭 cin 与 stdio 同步
    cin.tie(nullptr);              // 解除 cin/cout 绑定

    int t;
